from fractions import Fraction as Fr
from collections import Counter
import json

# c = 20/(-24) - (2 + -3)
c = Fr(20, -24) - (2 + -3)

# p(x) = (1/16)x^4 + 1 + (1/8)x^2 + 0*x - c*x^3, stored as {power: coefficient}
p = {4: Fr(1, 16), 3: -c, 2: Fr(1, 8), 1: Fr(0), 0: Fr(1)}

# k(x) = p'(x)
k = {n - 1: n * a for n, a in p.items() if n > 0}
deg = max(e for e, a in k.items() if a != 0)
coef = [k.get(i, Fr(0)) for i in range(deg, -1, -1)]  # highest power first


def ev(cs, x):
    r = Fr(0)
    for a in cs:
        r = r * x + a
    return r


def synth(cs, r):
    out = []
    acc = Fr(0)
    for a in cs:
        acc = acc * r + a
        out.append(acc)
    return out[:-1], out[-1]  # quotient coefficients, remainder


# Exhaustive finite enumeration of rational candidates p/q
cands = sorted({Fr(pn, q) for q in range(1, 13) for pn in range(-24, 25)},
               key=lambda x: (abs(x), x))

roots = []
cs = coef[:]
while len(cs) > 1:
    found = None
    for r in cands:
        if ev(cs, r) == 0:
            found = r
            break
    if found is None:
        break
    cs, rem = synth(cs, found)
    roots.append(found)

if len(cs) != 1:
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"reason": "no full rational factorization found"}}))
else:
    lead = coef[0]
    # Verify factorization at sample points
    ok = True
    for x in range(-4, 5):
        X = Fr(x)
        prod = lead
        for r in roots:
            prod *= (X - r)
        if prod != ev(coef, X):
            ok = False
            break

    if not ok:
        print(json.dumps({"final_answer": "UNSUPPORTED",
                          "evidence": {"reason": "factorization failed verification"}}))
    else:
        mult = Counter(roots)
        parts = []
        for r in sorted(mult):
            m = mult[r]
            if r == 0:
                base = "s"
            elif r > 0:
                base = f"(s - {r})"
            else:
                base = f"(s + {-r})"
            parts.append(base if m == 1 else f"{base}**{m}")
        lead_str = "" if lead == 1 else f"({lead})*"
        factored = f"{lead_str}{'*'.join(parts)}"

        result = {
            "final_answer": f"k(s) = {factored}",
            "evidence": {
                "c": str(c),
                "k_coeffs_high_to_low": [str(a) for a in coef],
                "roots_with_multiplicity": {str(r): mult[r] for r in sorted(mult)},
                "leading_coefficient": str(lead),
                "verified_at_sample_points": ok,
            },
        }
        print(json.dumps(result))
